                                                    }

                                                    #fichaMACLevantamiento .mac-ind-frecuencia strong {
                                                        color: #007DBA;
                                                    }

                                                    /* ANÁLISIS DE RESULTADOS */
                                                    #fichaMACLevantamiento .mac-ind-analisis {
                                                        margin-top: 18px;
                                                        padding: 15px;
                                                        border: 1px solid #d5d5d5;
                                                        border-radius: 4px;
